export function requireOwnerOrAdmin(paramName: string) {
  return function ownerOrAdmin(req, res, next) {
    const targetId = req.params[paramName];
    if (req.user.role === "admin" || req.user.id === targetId) {
      return next();
    }
    return res.status(403).json({ error: "forbidden" });
  };
}

router.patch(
  "/accounts/:accountId/email",
  requireAuth,
  validateEmailBody,
  requireOwnerOrAdmin("accountId"),
  updateEmail,
);

export async function updateEmail(req, res) {
  const account = await db.account.findUnique({
    where: { id: req.params.accountId },
  });

  if (!account) {
    return res.status(404).json({ error: "not_found" });
  }

  await db.account.update({
    where: { id: account.id },
    data: { email: req.body.email },
  });

  return res.json({ ok: true });
}
```

### Change intent / acceptance criteria

A signed-in user may update only their own account email. Administrators may update any account.

### Runtime / language context

- TypeScript
- Express router
- `requireAuth` supplies `req.user.id` and `req.user.role` before later middleware executes
- the shown route composition is the complete route-level chain for this endpoint

### Expected behavior / invariants

A non-admin user must not modify another user's account.

### Relevant contracts / constraints

`requireOwnerOrAdmin` is the authorization guard used by this route and its implementation is supplied above. `validateEmailBody` handles the email-body schema and is outside the authorization invariant under review.

